readonly struct CacheResult<T>
{
    public bool Hit { get; }
    public T? Value { get; }
    public string? Error { get; }

    private CacheResult(bool hit, T? value, string? error)
    {
        Hit = hit;
        Value = value;
        Error = error;
    }

    public static CacheResult<T> Miss() => new(false, default, null);
    public static CacheResult<T> Found(T value) => new(true, value, null);
    public static CacheResult<T> Fault(string error) => new(false, default, error);
}

CacheResult<SessionDto> ReadSession(IDatabase redis, string key)
{
    RedisValue raw = redis.StringGet(key);
    if (!raw.HasValue) return CacheResult<SessionDto>.Miss();
    try
    {
        SessionDto? dto = JsonSerializer.Deserialize<SessionDto>((string)raw!);
        return dto is null
            ? CacheResult<SessionDto>.Fault("null json")
            : CacheResult<SessionDto>.Found(dto);
    }
    catch (JsonException ex)
    {
        return CacheResult<SessionDto>.Fault(ex.Message);
    }
}
